#include <stdio.h>



int main(void) {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        long long value = 1;
        for (int j = 0; j <= i; j++) {
            printf("%s%lld", j ? " " : "", value);
            value = value * (i - j) / (j + 1);
        }
        putchar('\n');
    }
    return 0;
}
